// Builds extension/fillInPage.js from src/login/formFill.js, so the extension fills login
// forms with exactly the same code as the app's Sign in feature (which is tested against
// many form layouts). The extension cannot require files from src/, so the function's
// source is copied in; a test (npm run test:fill) fails if the copy is out of date.
//   npm run extension:sync-fill        rewrite the generated file
const fs = require("fs");
const path = require("path");
const { fillLoginForm } = require("../src/login/formFill");

const OUTPUT = path.join(__dirname, "..", "extension", "fillInPage.js");

// The text chrome.scripting.executeScript will serialise and run inside the page (in the
// extension's isolated world). It must be completely self-contained.
function buildSource() {
  const inner = fillLoginForm
    .toString()
    .split("\n")
    .map((line) => (line ? `  ${line}` : line))
    .join("\n");

  return `// GENERATED by scripts/sync-extension-fill.js from src/login/formFill.js. Do not edit by hand:
// run "npm run extension:sync-fill" after changing the app's form filler.
//
// Runs inside the page (isolated world), started by the background worker with the
// page's expected origin, the credentials and the options. Everything it needs is inside
// this one function, because only its text is sent to the page.
//   status: "filled" | "username-only" | "no-form" | "blocked"
// The result never contains the credentials.
function slvFillInPage(expectedOrigin, credentials, options) {
  // The page may have moved on since the credentials were requested.
  if (typeof expectedOrigin !== "string" || location.origin !== expectedOrigin) {
    return { status: "blocked" };
  }

${inner}

  if (options && options.inlineToken) {
    const context = globalThis.slvInlineContext;
    if (!context || context.token !== options.inlineToken || context.expires <= Date.now() ||
        context.url !== location.href || !context.target?.isConnected || context.target.form !== context.form ||
        !context.form?.isConnected || new URL(context.form.action || location.href, location.href).origin !== location.origin) {
      return { status: "blocked" };
    }
    globalThis.slvInlineContext = null;
    return fillLoginForm(document, credentials, { ...options, targetInput: context.target });
  }
  return fillLoginForm(document, credentials, options);
}
`;
}

if (require.main === module) {
  fs.writeFileSync(OUTPUT, buildSource());
  console.log(`Wrote ${path.relative(process.cwd(), OUTPUT)}`);
}

module.exports = { buildSource, OUTPUT };
